const app = document.querySelector('#app');

function element(tag, options = {}) {
  const node = document.createElement(tag);
  if (options.text !== undefined) node.textContent = options.text;
  if (options.className) node.className = options.className;
  if (options.testId) node.dataset.testid = options.testId;
  return node;
}

async function loadProjects(filter = 'Active') {
  const response = await fetch(`/api/projects?filter=${filter}`);
  if (!response.ok) throw new Error('Could not load projects');
  return response.json();
}

async function showProject(projectId) {
  const [activeProjects, archivedProjects] = await Promise.all([
    loadProjects('Active'), loadProjects('Archived'),
  ]);
  const project = [...activeProjects, ...archivedProjects].find((item) => String(item.id) === projectId);
  if (!project) {
    history.replaceState(null, '', '/');
    await render();
    return;
  }

  app.replaceChildren();
  const back = element('button', { text: 'Projects', className: 'back-button' });
  back.type = 'button';
  back.addEventListener('click', () => { location.href = '/'; });
  const heading = element('h1', { text: project.name });
  app.append(back, heading);
  if (project.archived) app.append(element('p', { text: 'Archived project', className: 'archive-notice' }));

  const alert = element('p', { className: 'alert' });
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  app.append(alert);

  const renameForm = element('form');
  const renameLabel = element('label', { text: 'New project name' });
  const renameInput = element('input');
  renameInput.type = 'text';
  renameInput.name = 'newProjectName';
  renameLabel.append(renameInput);
  const renameButton = element('button', { text: 'Rename project' });
  renameButton.type = 'submit';
  renameButton.disabled = project.archived;
  renameForm.append(renameLabel, renameButton);
  renameForm.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = renameInput.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      renameInput.focus();
      return;
    }
    renameButton.disabled = true;
    try {
      const response = await fetch(`/api/projects/${projectId}/rename`, {
        method: 'PATCH',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      if (!response.ok) throw new Error('Could not rename project');
      heading.textContent = name;
      renameInput.value = '';
      alert.hidden = true;
    } catch {
      alert.textContent = 'Could not rename project';
      alert.hidden = false;
    } finally {
      renameButton.disabled = project.archived;
    }
  });
  app.append(renameForm);

  const form = element('form');
  const label = element('label', { text: 'Task title' });
  const input = element('input');
  input.type = 'text';
  input.name = 'taskTitle';
  label.append(input);
  const create = element('button', { text: 'Create task' });
  create.type = 'submit';
  create.disabled = project.archived;
  form.append(label, create);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const title = input.value.trim();
    if (!title) {
      alert.textContent = 'Task title is required';
      alert.hidden = false;
      input.focus();
      return;
    }
    try {
      const response = await fetch(`/api/projects/${projectId}/tasks`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ title }),
      });
      if (!response.ok) throw new Error('Could not create task');
      await loadTasks();
      input.value = '';
      alert.hidden = true;
    } catch {
      alert.textContent = 'Could not create task';
      alert.hidden = false;
    }
  });
  app.append(form);

  const filterLabel = element('label', { text: 'Task filter', className: 'filter-label' });
  const filter = element('select');
  filter.setAttribute('aria-label', 'Task filter');
  for (const value of ['All', 'Open', 'Completed']) {
    const option = element('option', { text: value });
    option.value = value;
    filter.append(option);
  }
  filterLabel.append(filter);
  app.append(filterLabel);
  const taskList = element('section', { className: 'task-list', testId: 'task-list' });
  app.append(taskList);

  async function loadTasks() {
    const response = await fetch(`/api/projects/${projectId}/tasks`);
    if (!response.ok) throw new Error('Could not load tasks');
    const tasks = await response.json();
    taskList.replaceChildren();
    const visibleTasks = tasks.filter((task) => filter.value === 'All'
      || (filter.value === 'Open' && !task.completed)
      || (filter.value === 'Completed' && task.completed));
    for (const task of visibleTasks) {
      const row = element('div', { className: 'task-row', testId: 'task-row' });
      const checkboxLabel = element('label', { className: 'task-checkbox' });
      const checkbox = element('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = project.archived;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        try {
          const update = await fetch(`/api/projects/${projectId}/tasks/${task.id}`, {
            method: 'PATCH',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          if (!update.ok) throw new Error('Could not update task');
          await loadTasks();
        } catch {
          checkbox.checked = task.completed;
          checkbox.disabled = false;
          alert.textContent = 'Could not update task';
          alert.hidden = false;
        }
      });
      checkboxLabel.append(checkbox, element('span', { text: task.title }));
      row.append(checkboxLabel);
      taskList.append(row);
    }
  }
  filter.addEventListener('change', () => { loadTasks().catch(() => { alert.textContent = 'Could not load tasks'; alert.hidden = false; }); });
  await loadTasks();
}

async function showProjects() {
  app.replaceChildren();
  app.append(element('h1', { text: 'Workboard' }));

  const alert = element('p', { className: 'alert' });
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  app.append(alert);

  const filterLabel = element('label', { text: 'Project filter', className: 'filter-label' });
  const filter = element('select');
  filter.setAttribute('aria-label', 'Project filter');
  for (const value of ['Active', 'Archived']) {
    const option = element('option', { text: value });
    option.value = value;
    filter.append(option);
  }
  filterLabel.append(filter);
  app.append(filterLabel);
  const projectList = element('section', { className: 'project-list' });
  app.append(projectList);

  const form = element('form');
  const label = element('label', { text: 'Project name' });
  const input = element('input');
  input.type = 'text';
  input.name = 'projectName';
  label.append(input);
  const create = element('button', { text: 'Create project' });
  create.type = 'submit';
  form.append(label, create);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      input.focus();
      return;
    }
    const response = await fetch('/api/projects', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    if (!response.ok) {
      alert.textContent = 'Could not create project';
      alert.hidden = false;
      return;
    }
    await render();
  });
  app.append(form);

  async function renderProjects() {
    const projects = await loadProjects(filter.value);
    projectList.replaceChildren();
    for (const project of projects) {
      const row = element('div', { className: 'project-row', testId: 'project-row' });
      const details = element('div', { className: 'project-details' });
      details.append(element('span', { text: project.name, className: 'project-name' }));
      details.append(element('span', { text: `${project.completedCount}/${project.totalCount} completed`, testId: 'project-summary' }));
      const actions = element('div', { className: 'project-actions' });
      const open = element('button', { text: 'Open project' });
      open.type = 'button';
      open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
      const stateButton = element('button', { text: project.archived ? 'Restore project' : 'Archive project', className: 'secondary-button' });
      stateButton.type = 'button';
      stateButton.addEventListener('click', async () => {
        stateButton.disabled = true;
        try {
          const response = await fetch(`/api/projects/${project.id}/archive`, {
            method: 'PATCH', headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ archived: !project.archived }),
          });
          if (!response.ok) throw new Error('Could not update project');
          await renderProjects();
        } catch {
          stateButton.disabled = false;
          alert.textContent = 'Could not update project';
          alert.hidden = false;
        }
      });
      actions.append(open, stateButton);
      row.append(details, actions);
      projectList.append(row);
    }
  }
  filter.addEventListener('change', () => { renderProjects().catch(() => { alert.textContent = 'Could not load projects'; alert.hidden = false; }); });
  await renderProjects();
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { mkdir } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';

const port = Number.parseInt(process.env.PORT ?? '8080', 10);
const databasePath = resolve(process.env.DB_PATH ?? 'workboard.sqlite');
await mkdir(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))
  )
`);
// Upgrade databases created by earlier Workboard tasks.
const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
database.exec(`
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  )
`);
database.exec('PRAGMA foreign_keys = ON');

const page = await readFile(new URL('./public/index.html', import.meta.url));
const styles = await readFile(new URL('./public/styles.css', import.meta.url));
const client = await readFile(new URL('./public/app.js', import.meta.url));

function send(response, status, contentType, body) {
  response.writeHead(status, { 'content-type': contentType, 'x-content-type-options': 'nosniff' });
  response.end(body);
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (body.length > 10_000) throw new Error('Request body too large');
  }
  return JSON.parse(body);
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, `http://${request.headers.host ?? 'localhost'}`);
  if (request.method === 'GET' && url.pathname === '/health') {
    send(response, 200, 'application/json; charset=utf-8', JSON.stringify({ status: 'ok' }));
    return;
  }

  if (request.method === 'GET' && url.pathname === '/api/projects') {
    const filter = url.searchParams.get('filter') === 'Archived' ? 1 : 0;
    const projects = database.prepare(`
      SELECT p.id, p.name, p.archived,
        COUNT(t.id) AS totalCount,
        SUM(CASE WHEN t.completed = 1 THEN 1 ELSE 0 END) AS completedCount
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      WHERE p.archived = ? GROUP BY p.id ORDER BY p.id
    `).all(filter).map((project) => ({
      ...project,
      archived: Boolean(project.archived),
      totalCount: Number(project.totalCount),
      completedCount: Number(project.completedCount ?? 0),
    }));
    send(response, 200, 'application/json; charset=utf-8', JSON.stringify(projects));
    return;
  }

  const projectStateRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/archive$/);
  if (projectStateRoute && request.method === 'PATCH') {
    try {
      const payload = await readJson(request);
      if (typeof payload.archived !== 'boolean') {
        send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid archive state' }));
        return;
      }
      const result = database.prepare('UPDATE projects SET archived = ? WHERE id = ?')
        .run(payload.archived ? 1 : 0, Number(projectStateRoute[1]));
      if (result.changes === 0) {
        send(response, 404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project not found' }));
        return;
      }
      send(response, 200, 'application/json; charset=utf-8', JSON.stringify({ archived: payload.archived }));
    } catch {
      send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid request' }));
    }
    return;
  }

  const renameProjectRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/rename$/);
  if (renameProjectRoute && request.method === 'PATCH') {
    try {
      const payload = await readJson(request);
      const name = typeof payload.name === 'string' ? payload.name.trim() : '';
      if (!name) {
        send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project name is required' }));
        return;
      }
      const result = database.prepare('UPDATE projects SET name = ? WHERE id = ?')
        .run(name, Number(renameProjectRoute[1]));
      if (result.changes === 0) {
        send(response, 404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project not found' }));
        return;
      }
      send(response, 200, 'application/json; charset=utf-8', JSON.stringify({ name }));
    } catch {
      send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid request' }));
    }
    return;
  }

  if (request.method === 'POST' && url.pathname === '/api/projects') {
    try {
      const payload = await readJson(request);
      const name = typeof payload.name === 'string' ? payload.name.trim() : '';
      if (!name) {
        send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project name is required' }));
        return;
      }
      const result = database.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      send(response, 201, 'application/json; charset=utf-8', JSON.stringify({ id: Number(result.lastInsertRowid), name }));
    } catch {
      send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid request' }));
    }
    return;
  }

  const tasksRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksRoute && request.method === 'GET') {
    const tasks = database.prepare(
      'SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id'
    ).all(Number(tasksRoute[1])).map((task) => ({ ...task, completed: Boolean(task.completed) }));
    send(response, 200, 'application/json; charset=utf-8', JSON.stringify(tasks));
    return;
  }
  if (tasksRoute && request.method === 'POST') {
    try {
      const projectId = Number(tasksRoute[1]);
      const project = database.prepare('SELECT id FROM projects WHERE id = ?').get(projectId);
      if (!project) {
        send(response, 404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project not found' }));
        return;
      }
      const projectState = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
      if (projectState.archived) {
        send(response, 409, 'application/json; charset=utf-8', JSON.stringify({ error: 'Archived project' }));
        return;
      }
      const payload = await readJson(request);
      const title = typeof payload.title === 'string' ? payload.title.trim() : '';
      if (!title) {
        send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Task title is required' }));
        return;
      }
      const result = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
      send(response, 201, 'application/json; charset=utf-8', JSON.stringify({
        id: Number(result.lastInsertRowid), projectId, title, completed: false,
      }));
    } catch {
      send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid request' }));
    }
    return;
  }

  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (taskRoute && request.method === 'PATCH') {
    try {
      const projectId = Number(taskRoute[1]);
      const taskId = Number(taskRoute[2]);
      const projectState = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
      if (!projectState) {
        send(response, 404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Project not found' }));
        return;
      }
      if (projectState.archived) {
        send(response, 409, 'application/json; charset=utf-8', JSON.stringify({ error: 'Archived project' }));
        return;
      }
      const payload = await readJson(request);
      if (typeof payload.completed !== 'boolean') {
        send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid completion state' }));
        return;
      }
      const result = database.prepare(
        'UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?'
      ).run(payload.completed ? 1 : 0, taskId, projectId);
      if (result.changes === 0) {
        send(response, 404, 'application/json; charset=utf-8', JSON.stringify({ error: 'Task not found' }));
        return;
      }
      send(response, 200, 'application/json; charset=utf-8', JSON.stringify({ id: taskId, projectId, completed: payload.completed }));
    } catch {
      send(response, 400, 'application/json; charset=utf-8', JSON.stringify({ error: 'Invalid request' }));
    }
    return;
  }

  if (request.method === 'GET' && url.pathname === '/styles.css') {
    send(response, 200, 'text/css; charset=utf-8', styles);
    return;
  }
  if (request.method === 'GET' && url.pathname === '/app.js') {
    send(response, 200, 'text/javascript; charset=utf-8', client);
    return;
  }
  if (request.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    send(response, 200, 'text/html; charset=utf-8', page);
    return;
  }
  send(response, 404, 'text/plain; charset=utf-8', 'Not found');
});

